            i += 1
            continue

        match = number_pattern.match(expr, i)
        if match:
            tokens.append(("NUM", float(match.group())))
            i = match.end()
            # Reject malformed numbers like "1.2.3" or "1..2"
            if i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                raise ValueError("Malformed number")
        elif expr[i] in "+-*/()":
            tokens.append(("OP", expr[i]))
            i += 1
        else:
            raise ValueError(f"Unknown character: {expr[i]}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0
    n = len(tokens)

    def peek():
        return tokens[pos] if pos < n else None

    def consume(expected=None):
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if expected is not None and tok != expected:
            raise ValueError(f"Expected {expected}, got {tok}")
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in (("OP", "+"), ("OP", "-")):
            op = consume()[1]
            right = parse_term()
            val = val + right if op == "+" else val - right
        return val

    def parse_term():
        val = parse_factor()
        while peek() in (("OP", "*"), ("OP", "/")):
            op = consume()[1]
            right = parse_factor()
            if op == "*":
                val *= right
            else:
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                val /= right
        return val

    def parse_factor():
        tok = peek()
        if tok is None:
            raise ValueError("Trailing operator or missing operand")
        if tok == ("OP", "-"):
            consume()
            return -parse_factor()
        if tok[0] == "NUM":
            consume()
            return tok[1]
        if tok == ("OP", "("):
            consume()
            val = parse_expr()
            consume(("OP", ")"))
            return val
        raise ValueError(f"Unexpected token: {tok}")

    res = parse_expr()

    if pos < n:
        raise ValueError("Unmatched token or unbalanced parentheses")

    return float(res)
